// Keep the runtime payload compatible with Pages' older JavaScript bundler.
export function calibrationModule(data) {
  const runtime = {
    fetchedAt: data.fetchedAt,
    caveat: data.caveat,
    sampleSize: data.samples.length,
    methods: data.methods,
    participation: data.participation,
  };
  return (
    "// Generated by npm run calibrate. Raw observations: calibration.json.\nexport default " +
    JSON.stringify(runtime, null, 2) +
    ";\n"
  );
}
